      "Mehl mit Backpulver mischen. Zusammen mit den flüssigen Zutaten nur so kurz unterrühren, bis kein trockenes Mehl mehr zu sehen ist. Backkakao zusammen mit dem Mehl sieben, damit keine trockenen Kakaonester bleiben.",
