    "steps": [
      "Für den Hefeteig Mehl, Trockenhefe und 70 g Zucker mischen. 250 ml Milch nur handwarm erwärmen und mit 80 g weicher Butter und dem Ei zugeben. 8 bis 10 Minuten kneten, bis der Teig glatt und elastisch ist.",
      "Teig abgedeckt 50 bis 60 Minuten an einem warmen, zugfreien Ort gehen lassen, bis er sein Volumen deutlich vergrößert hat. Anschließend auf ein gefettetes oder mit Backpapier belegtes Blech drücken und bis in die Ecken ziehen.",
      "Für den Mandelbelag 100 g Butter, 80 g Zucker, 60 g Honig und 100 ml Sahne in einem kleinen Topf unter Rühren erhitzen, bis alles verbunden ist. Mandelblättchen einrühren, 3 bis 4 Minuten abkühlen lassen und die noch streichfähige Masse vorsichtig auf dem Hefeteig verteilen.",
      "Blech nochmals 15 bis 20 Minuten ruhen lassen. Backofen währenddessen auf 200 °C Ober-/Unterhitze vorheizen.",
      "Auf der mittleren Schiene 18 bis 22 Minuten backen. Der Mandelbelag soll kräftig goldbraun sein und der Hefeboden an den Rändern trocken wirken. Anschließend vollständig auskühlen lassen.",
      "Für die Füllung aus 500 ml Milch, 40 g Puddingpulver und 40 g Zucker einen festen Vanillepudding kochen. Direkt an der Oberfläche abdecken und vollständig auskühlen lassen. 200 ml Sahne steif schlagen und den kalten Pudding erst glatt rühren, dann die Sahne vorsichtig unterheben.",
      "Den ausgekühlten Kuchen in 12 Stücke schneiden und jedes Stück waagerecht halbieren. Unterseiten mit der Vanillecreme füllen, Mandeloberseiten wieder aufsetzen und den Bienenstich bis zum Servieren kalt stellen."
    ],
