      "Backofen auf 180 °C Ober-/Unterhitze vorheizen. Backblech mit Backpapier auslegen oder eine große rechteckige Form einfetten.",
      "Aus Mehl, Zucker, Butter, Ei und Backpulver zuerst mit den Knethaken, dann kurz mit den Händen einen streuseligen Teig herstellen. Etwa zwei Drittel als Boden festdrücken, den Rest kalt stellen.",
      "Rhabarber vorbereiten und gleichmäßig auf dem Boden verteilen. Sehr saftiges Obst vorher gut abtropfen lassen, damit der Boden nicht durchweicht.",
      "Restlichen Teig grob zwischen den Fingern zu Streuseln reiben und locker über der Füllung verteilen. Streusel nicht festdrücken.",
      "Auf der mittleren Schiene 40 bis 45 Minuten backen. Der Rand soll goldbraun sein und die Streusel trocken und knusprig aussehen.",
      "Kuchen vollständig in der Form auskühlen lassen. Besonders bei saftiger Füllung erst kalt schneiden, damit Boden und Belag stabil bleiben."
