    "steps": [
      "Backofen auf 180 °C Ober-/Unterhitze vorheizen. 26-cm-Springform dünn einfetten und, wenn die Form es zulässt, den Boden mit Backpapier auslegen.",
      "Weiche Butter mit Zucker 3 bis 4 Minuten hell und cremig schlagen. Die Eier einzeln jeweils etwa 30 Sekunden einarbeiten, damit die Masse glatt bleibt und nicht gerinnt.",
      "Mehl mit Backpulver mischen. Zusammen mit den flüssigen Zutaten nur so kurz unterrühren, bis kein trockenes Mehl mehr zu sehen ist. Die fein geriebenen Möhren zuletzt mit einem Teigschaber unterheben.",
      "Teig gleichmäßig in die vorbereitete Form geben und die Oberfläche glatt streichen. Auf der mittleren Schiene etwa 45 Minuten backen.",
      "Gegen Ende die passende Garprobe machen: Ein Holzstäbchen in die dickste Stelle stecken. Es dürfen feuchte Krümel, aber kein flüssiger Teig daran hängen.",
      "Kuchen 10 Minuten in der Form stehen lassen, dann vorsichtig lösen und auf einem Gitter vollständig auskühlen lassen. Erst kalt schneiden oder glasieren, damit er nicht bricht."
    ],
